        if (AGENT_EVENT_METHODS.has(method)) {
            return this.dispatcher.invoke(method, [...params, (event) => sendJson(client, { event: 'agentRun', payload: { event, requestId: id } })]);
        }

        return this.dispatcher.invoke(method, params);
