    subscriptionId: string
}

interface WorktreesChangedPayload {
    requestId: string
    state: WorktreeState
    subscriptionId: string
}

interface ProjectWatchSubscription {
    onChange: (event: ProjectWatchEvent) => void
    onError: (error: Error) => void
